expression:
grel:with(
  split(value, ",", true),
  p,
  if(p.length()==3,
    p[1].trim() + " " + p[0].trim() + ", " + p[2].trim(),
    if(p.length()==2,
      p[1].trim() + " " + p[0].trim(),
      value
    )
  )
)

